function problemText(code){if(code==='christmas-cutoff')return s('The Christmas planning cut-off for this length and delivery format has passed. Choose digital delivery, a shorter piece or a later occasion. We confirm availability before payment.','Planleggingsfristen til jul for denne lengden og leveringsmåten har passert. Velg digital levering, kortere tekst eller en senere anledning. Vi bekrefter kapasiteten før betaling.');return s(({deadline:'Choose the date you need the gift by.',occasion:'Choose the occasion date or select no particular occasion.','occasion-order':'Your delivery deadline must be on or before the occasion.','too-soon':'Please choose a later deadline so there is enough time for writing and delivery.',destination:'This destination needs a delivery quote. Choose a supported destination for now.',reply:'Paste the exact incoming letter or upload a readable copy before continuing.','book-digital':'Personal books are digital-only.'})[code]||'Please check the details.',({deadline:'Velg datoen du trenger gaven innen.',occasion:'Velg anledningsdato eller ingen bestemt anledning.','occasion-order':'Leveringsfristen må være på eller før anledningen.','too-soon':'Velg en senere frist så det er nok tid til skriving og levering.',destination:'Dette mottakerlandet trenger et leveringstilbud.',reply:'Lim inn det nøyaktige brevet eller last opp en leselig kopi.','book-digital':'Personlige bøker er bare digitale.'})[code]||'Se over detaljene.')}
function bind(){bindPlanner({s,date});for(const [id,k] of [['siteLang','lang'],['currency','currency']])$(id).onchange=e=>{prefs[k]=e.target.value;store('dw-settings',prefs);render();$(id).focus()};$('simpleToggle').onclick=()=>{prefs.simple=!prefs.simple;store('dw-settings',prefs);render()};$('readingToggle').onclick=()=>{const open=$('readingOptions').hidden;$('readingOptions').hidden=!open;$('readingToggle').setAttribute('aria-expanded',String(open))};for(const [id,k] of [['largeToggle','large'],['contrastToggle','contrast']])$(id).onclick=()=>{prefs[k]=!prefs[k];store('dw-settings',prefs);document.documentElement.classList.toggle('large',prefs.large);document.body.classList.toggle('contrast',prefs.contrast);$(id).setAttribute('aria-pressed',String(prefs[k]))};
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;updateShop();document.querySelector('[data-filter="'+filter+'"]')?.focus()});if($('shopOccasion'))$('shopOccasion').onchange=e=>{occasionFilter=e.target.value;updateShop('shopOccasion')};if($('shopRecipient'))$('shopRecipient').onchange=e=>{recipientFilter=e.target.value;updateShop('shopRecipient')};if($('clearFilters'))$('clearFilters').onclick=()=>{filter=occasionFilter=recipientFilter='all';updateShop('shopOccasion')};document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{cart.splice(Number(b.dataset.remove),1);store('dw-basket',cart);render()});if($('orderForm'))bindOrder();if($('checkoutForm'))bindCheckout();if(path==='/help')bindFinder();if(path==='/account')loadAccount();if(path==='/studio')bindStudio(supportUI());if(path==='/customer-service'||path==='/customer-service/inbox')bindSupport(supportUI(),path.endsWith('/inbox'))}
function bindOrder(){const form=$('orderForm');form.querySelectorAll('input,select,textarea').forEach(el=>{if(el.type==='file')return;el.oninput=()=>{draft[el.id]=el.type==='checkbox'?el.checked:el.id==='words'?Number(el.value):el.value};if(['format','country','postService','words','noOccasion','audience','occasion'].includes(el.id))el.onchange=()=>{draft[el.id]=el.type==='checkbox'?el.checked:el.id==='words'?Number(el.value):el.value;render()}});if($('needBy'))$('needBy').min=deliveryPlan(draft).earliest;$('back')?.addEventListener('click',()=>{stage--;render(true)});form.onsubmit=e=>{e.preventDefault();if(stage===0){const code=validateRequest({...draft,key:draft.key==='continuation'?'letter':draft.key});if(code){$('formError').textContent=problemText(code);return}}if(stage===1){const code=validateRequest(draft);if(code){$('formError').textContent=problemText(code);return}if(draft.brief.trim().length<15){$('formError').textContent=s('Please give us a little more detail for the writer.','Gi skribenten litt mer informasjon.');return}}if(stage<2){stage++;render(true)}else{if(editing)cart[editIndex]={...draft};else cart.push({...draft});store('dw-basket',cart);location.href='/basket/'}};document.querySelectorAll('[data-unlink]').forEach(b=>b.onclick=()=>{draft.attachments=draft.attachments.filter(x=>x.id!==b.dataset.unlink);render()});if($('upload'))$('upload').onclick=async()=>{const f=$('letterFile').files[0];if(!f||f.size>5*1024*1024||draft.attachments.length>=2){$('uploadStatus').textContent=s('Choose up to two files, each no larger than 5 MB.','Velg opptil to filer på maksimalt 5 MB hver.');return}$('upload').disabled=true;try{const fd=new FormData();fd.append('file',f);const r=await fetch('/api/attachments',{method:'POST',body:fd});const d=await r.json();if(!r.ok)throw Error(d.error);draft.attachments.push(d);render()}catch(e){$('uploadStatus').textContent=e.message;$('upload').disabled=false}}}
function requestId(){if(typeof crypto.randomUUID==='function')return crypto.randomUUID();const bytes=crypto.getRandomValues(new Uint8Array(16));bytes[6]=(bytes[6]&15)|64;bytes[8]=(bytes[8]&63)|128;const h=Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');return [h.slice(0,8),h.slice(8,12),h.slice(12,16),h.slice(16,20),h.slice(20)].join('-')}
function bindCheckout(){const clientKey=requestId();$('checkoutForm').querySelectorAll('input,textarea').forEach(el=>el.oninput=()=>contactDraft[el.id]=el.value);$('checkoutForm').onsubmit=async e=>{e.preventDefault();if(new Set(cart.filter(x=>x.format!=='digital').map(x=>x.country)).size>1){$('checkoutError').textContent=s('Please place separate requests for different posting countries.','Legg inn separate forespørsler for ulike mottakerland.');return}$('submitRequest').disabled=true;const contact=Object.fromEntries(new FormData($('checkoutForm')).entries());try{const r=await fetch('/api/orders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({clientKey,items:cart,contact,currency:prefs.currency,consent:$('requestConsent').checked,termsConsent:$('termsConsent').checked,adultConsent:$('adultConsent').checked,earlyStart:$('earlyStart').checked})});const d=await r.json();if(!r.ok)throw Error(d.error||'Unable to save');savedOrder=d;cart=[];store('dw-basket',cart);render(true)}catch(err){$('checkoutError').textContent=err.message;$('submitRequest').disabled=false}}}
function bindFinder(){const steps=finderSteps(),step=steps[finderStage];document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{finder[step.key]=b.dataset.answer;if(step.key==='recipient')finder.occasion='';if(step.key==='style'&&b.dataset.answer==='book')finder.format='digital';finderStage++;render(true)});$('finderBack')?.addEventListener('click',()=>{finderStage--;render(true)});$('finderReset')?.addEventListener('click',()=>{finderStage=0;finder={recipient:'',occasion:'',style:'',budget:'',format:'digital',country:'uk',details:''};render(true)});if($('finderDetailsForm'))$('finderDetailsForm').onsubmit=e=>{e.preventDefault();finder.details=$('finderDetails').value;finderStage++;render(true)};document.querySelectorAll('.use-recommendation').forEach(a=>a.onclick=()=>{const brief=[s('Gift finder notes','Notater fra gaveveiviseren'),s('For: ','Til: ')+finderLabel(finder.recipient),s('Occasion: ','Anledning: ')+finderLabel(finder.occasion),finder.details].filter(Boolean).join('\n');sessionStorage.setItem('dw-finder-brief',JSON.stringify({key:a.dataset.product,words:Number(a.dataset.words),format:a.dataset.format,country:finder.country,audience:finder.recipient==='child'?'child':'adult',brief,created:Date.now()}))})}
async function loadAccount(){const body=$('accountBody');try{const [r,o]=await Promise.all([fetch('/api/account'),fetch('/api/orders')]);if(!r.ok)throw Error('Unable to load account');const d=await r.json();if(!d.signedIn){body.innerHTML=`<h2>${s('Welcome to your writing corner.','Velkommen til skrivehjørnet ditt.')}</h2><p>${s('Sign in with ChatGPT to save and revisit your requests.','Logg inn med ChatGPT for å lagre og finne igjen forespørslene.')}</p><a href="/signin-with-chatgpt?return_to=%2Faccount%2F" class="button" target="_top">${s('Sign in with ChatGPT','Logg inn med ChatGPT')}</a>`;return}const orders=o.ok?(await o.json()).orders||[]:[];body.innerHTML=`<h2>${s('Your requests','Dine forespørsler')}</h2>${orders.length?orders.map(x=>`<details class="account-order"><summary>${esc(x.reference)} · ${statusLabel(x.status)}</summary><p>${new Date(x.createdAt).toLocaleDateString()}</p>${x.items.map(i=>`<h3>${name(i.key)}</h3>${review(i)}`).join('')}${orderActions(x)}</details>`).join(''):`<p>${s('No order requests yet. Your writing will appear here when you save a request at checkout.','Ingen bestillingsforespørsler ennå. De vises her når du lagrer en forespørsel i kassen.')}</p>`}${d.requests?.length?`<h2>${s('Earlier saved ideas','Tidligere lagrede ideer')}</h2>${d.requests.map(x=>`<details><summary>${new Date(x.createdAt).toLocaleDateString()}</summary>${x.items.map(i=>`<h3>${name(aliases[i.key]||i.key)}</h3><p class="preserve">${esc(i.brief)}</p>`).join('')}</details>`).join('')}`:''}<h2>${s('Your preferences','Dine valg')}</h2><label class="check"><input type="checkbox" id="followups" ${d.continuations?'checked':''}>${s('Show optional continuation ideas here for my past requests.','Vis valgfrie fortsettelsesideer her for tidligere forespørsler.')}</label><p class="hint">${s('Off by default. No automated emails, subscriptions or purchases.','Av som standard. Ingen automatiske e-poster, abonnementer eller kjøp.')}</p>${d.continuations&&orders.some(o=>o.items.some(i=>['magic','continuation','bedtime'].includes(i.key)))?`<aside class="notice"><h3>${s('Another chapter, only if you’d like one','Et nytt kapittel, bare hvis du ønsker')}</h3><p>${s('You can return to an earlier toy adventure with a follow-up letter. There is no need to keep ordering.','Du kan fortsette et tidligere lekeeventyr med et svarbrev. Du trenger ikke bestille mer.')}</p>${link('/commission/continuation/',s('Explore a follow-up','Se fortsettelsesbrev'),'text-link')}</aside>`:''}<p id="accountStatus" role="status"></p><section id="accountUploads"></section><p><a href="/signout-with-chatgpt?return_to=%2F" target="_top">${s('Sign out','Logg ut')}</a></p>`;$('followups').onchange=async e=>{const checked=e.target.checked;try{const r=await fetch('/api/account',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'preferences',continuations:checked})});if(!r.ok)throw Error('Unable to save preference');loadAccount()}catch(err){e.target.checked=!checked;$('accountStatus').textContent=err.message}};bindCustomerPayments();loadUploads();fetch('/api/studio').then(r=>{if(r.ok){const a=document.createElement('a');a.href='/studio/';a.className='button secondary';a.textContent=s('Open your owner studio','Åpne eierstudioet');body.prepend(a)}}).catch(()=>{})}catch(e){body.textContent=s('Your account could not be loaded. Please try again.','Kontoen kunne ikke lastes. Prøv igjen.')}}
async function loadUploads(){try{const r=await fetch('/api/attachments');if(!r.ok)return;const d=await r.json();if(!$('accountUploads'))return;$('accountUploads').innerHTML=`<h2>${s('Your uploaded letters','Dine opplastede brev')}</h2><p class="hint">${s('Private to your account. Deleting a file also removes it from previous saved requests.','Private for kontoen din. Sletting fjerner også filen fra tidligere forespørsler.')}</p>${d.files.length?d.files.map(f=>`<div class="file-row">${link('/api/attachments?id='+encodeURIComponent(f.id),esc(f.name))}${button(s('Delete file','Slett fil'),`class="text-button" data-delete-file="${esc(f.id)}"`)}</div>`).join(''):`<p>${s('No uploaded files.','Ingen opplastede filer.')}</p>`}`;document.querySelectorAll('[data-delete-file]').forEach(b=>b.onclick=async()=>{b.disabled=true;const r=await fetch('/api/attachments?id='+encodeURIComponent(b.dataset.deleteFile),{method:'DELETE'});if(r.ok)loadUploads();else{b.disabled=false;$('accountStatus').textContent=s('The file could not be deleted.','Filen kunne ikke slettes.')}})}catch{}}
const defaultGuideKeys=Object.keys(articles);
function applyWebsiteConfig(c){website=c;const safe=x=>Array.isArray(x)?x.map(safe):x&&typeof x==='object'?Object.fromEntries(Object.entries(x).map(([k,v])=>[k,safe(v)])):typeof x==='string'?esc(x):x;
 if(c.pricing){for(const kind of ['letter','story','book'])rates[kind]={...c.pricing.rates[kind]};Object.assign(currencies,c.pricing.currencies);Object.assign(printingCosts,c.pricing.printing);Object.assign(postageCosts,c.pricing.postage);}
 for(const [k,p]of Object.entries(c.products||{}))if(Object.hasOwn(catalogue,k))Object.assign(catalogue[k],safe(p));
 for(const [k,a]of Object.entries(c.articles||{}))articles[k]=safe(a);
 if(catalogue[key]&&!Object.hasOwn(rates[catalogue[key].kind],draft.words))draft.words=Number(Object.keys(rates[catalogue[key].kind])[0]);
}
if(typeof document!=='undefined'){
 (async()=>{try{const [cr,br]=await Promise.all([fetch('/api/website',{signal:AbortSignal.timeout(10000)}),fetch('/api/business',{signal:AbortSignal.timeout(10000)})]);if(!cr.ok||!br.ok)throw Error('Unable to load website settings.');applyWebsiteConfig(await cr.json());const d=await br.json();business=Object.fromEntries(Object.entries(d).map(([k,v])=>[k,typeof v==='string'?esc(v):v]));render();if(d.acceptingRequests===false){const notice=document.createElement('div');notice.className='commission-closed';notice.setAttribute('role','status');notice.textContent=s('Commissions are currently closed. You can explore ideas and return when requests reopen.','Skriveoppdrag er stengt for øyeblikket. Du kan utforske ideer og komme tilbake når vi åpner.');$('main').prepend(notice)}}catch{document.getElementById('app').textContent=s('We could not load the latest website settings. Please refresh and try again.','Vi kunne ikke laste siste nettstedsinnstillinger. Oppdater siden og prøv igjen.');}})();
}
